tests.code:
// 4.1 Navigate to Add Branch
cy.xpath(_locator.branchlocator.AddBranch).click({
  force: true
});
cy.url().should("include", "/branches/add");
// 4.2 Create branch
cy.get(_locator.branchlocator.BranchName).type(BranchName);
cy.get(_locator.branchlocator.Slug).type(Slug);
cy.get(_locator.branchlocator.BranchPhone).eq(0).clear().type("+977").type(Phone);
cy.get(_locator.branchlocator.BranchEmail).type(BranchEmail);
cy.xpath(_locator.branchlocator.Status).click();
cy.get('button[role="combobox"]').filter(':has(span[data-slot="select-value"])').then($btn => {
  if ($btn.attr("aria-expanded") === "false") {
    cy.wrap($btn).click();
  }
});
cy.get('[role="option"]').contains(/^Active$/).click({
  force: true
});
cy.get(_locator.branchlocator.Address).type("Kathmandu, Nepal");
cy.get(_locator.branchlocator.FirstName).type(FirstName);
cy.get(_locator.branchlocator.LastName).type(LastName);
cy.get(_locator.branchlocator.AdminEmail).type(AdminEmail);
cy.get(_locator.branchlocator.Password).type(Password);
cy.get(_locator.branchlocator.AdminPhone).eq(1).clear().type("+977" + Phone);
cy.xpath(_locator.branchlocator.CreateBranch).click();
cy.get("body").should("contain.text", BranchName);
// 4.3 Edit branch
cy.xpath(_locator.search.SearchField).type(BranchName);
cy.get("body").should("contain.text", BranchName);
cy.xpath(_locator.branchlocator.EditBranch).click({
  force: true
});
cy.get("body").should("contain.text", "Save Changes");
cy.get(_locator.branchlocator.BranchName).clear().type(`Edited Salon ${uniqueId}`);
cy.xpath(_locator.branchlocator.UpdateBranch).click({
  force: true
});
// 4.4 Delete branch
cy.xpath(_locator.search.SearchField).clear().type(`Edited Salon ${uniqueId}`);
cy.get("body").should("contain.text", `Edited Salon ${uniqueId}`);
// Select the branch checkbox
cy.xpath(`//tbody/tr[contains(., "Edited Salon ${uniqueId}")]//button[@aria-label="Select row"]`).click({
  force: true
});
cy.xpath('//button[normalize-space()="Delete"]').should("be.visible").click({
  force: true
});
// cy.xpath(branchlocator.DeleteBranch).first().click({ force: true });
// cy.wait(1000);
cy.xpath(_locator.branchlocator.ConfirmDelete).type("Delete Branch");
cy.xpath(_locator.branchlocator.Delete).click();
cy.xpath(_locator.search.SearchField).clear().type(BranchName, {
  force: true
});
cy.get("body").should("not.contain.text", `Edited Salon ${uniqueId}`);
